export const RemotionRoot: React.FC = () => {
  // const { video, isLoading, error, actions } = useVideoEditorContext();

  // Calculate frame number for display
  const fps = 30;
  const totalDuration = video
    ? video.segments.reduce(
        (total, segment) => total + (segment.duration || 0),
        0,
      )
    : 0;
  const totalFrames = Math.max(1, Math.floor(totalDuration * fps)); // Ensure at least 1 frame

  return (
    <>
      <Composition
        id="VideoComposition"
        className="h-80 w-full"
        component={VideoComposition}
        durationInFrames={totalFrames}
        compositionWidth={video.format?.width || 1080}
        compositionHeight={video.format?.height || 1920}
        fps={fps}
        width={video.format?.width || 1080}
        height={video.format?.height || 1920}
        style={{
          width: "100%",
          height: "100%",
        }}
        defaultProps={{
          project: video,
        }}
        autoPlay={false}
        controls={true}
        loop={false}
        allowFullscreen
        doubleClickToFullscreen
        showVolumeControls={true}
        spaceKeyToPlayOrPause={false}
      />
    </>
  );
};
